SELECT inventory.id, inventory.quantity, inventory.product_id, inventory.last_restock, store_sales.product_id AS store_sale_product_id, store_sales.sale_date, store_sales.store_id FROM inventory INNER JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE store_sales.sale_date < '2024-08-20' AND store_sales.sale_date <= '2023-09-01'
